const $ = (s) => document.querySelector(s);
let projects = [], current = null, quotation = null, sessionUser = null, replacementRules = [];
let catalogData = { materials: [], brands: [], products: [], prices: [] }, catalogLoaded = false;
let brandEditing = null;
const replacementRuleApi = async (id = "", options = {}) => api(`/api/replacement-rules${id ? `/${id}` : ""}`, options);
const esc = (s) => String(s ?? "").replace(/[&<>\"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const showNotice = (message, error = false) => { const el = $("#notice"); if (!el) return; el.textContent = message; el.classList.remove("hidden", "error"); if (error) el.classList.add("error"); };
function showLogin(message = "") { sessionUser = null; $("#loginState").classList.remove("hidden"); $(".shell").classList.add("hidden"); $("#logoutButton").classList.add("hidden"); $("#headerStatus").textContent = "未登录"; const err = $("#loginError"); err.textContent = message; err.classList.toggle("hidden", !message); }
function showApp(user) { sessionUser = user || null; $("#loginState").classList.add("hidden"); $(".shell").classList.remove("hidden"); $("#logoutButton").classList.remove("hidden"); $("#headerStatus").textContent = user?.platformRole === "platform_admin" ? `${user.email} · 平台管理员` : (user?.email || "已登录"); }
const api = async (url, options = {}) => { const res = await fetch(url, options); const data = await res.json().catch(() => ({})); if (res.status === 401) { showLogin(data.error || "请先登录"); throw new Error(data.error || "请先登录"); } if (!res.ok) throw new Error(data.error || `请求失败 ${res.status}`); return data; };
async function loadProjects() { projects = await api("/api/projects"); await loadCatalogData(); renderProjects(); if (current) { const refreshed = projects.find(p => p.id === current.id); if (refreshed) { current = refreshed; renderCurrent(); } } }
function renderProjects() { $("#projectList").innerHTML = projects.length ? projects.map(p => `<div class="project-item ${current?.id === p.id ? "active" : ""}" data-id="${p.id}"><div class="project-name">${esc(p.name)}</div><div class="project-status">${esc(p.status)} · ${new Date(p.updatedAt).toLocaleDateString("zh-CN")}</div></div>`).join("") : `<div class="project-status" style="padding:10px 8px">还没有项目</div>`; document.querySelectorAll(".project-item").forEach(el => el.addEventListener("click", () => openProject(el.dataset.id))); }
async function openProject(id) { current = await api(`/api/projects/${id}`); renderProjects(); renderCurrent(); }
function renderCurrent() { $("#emptyState").classList.add("hidden"); $("#quotationView").classList.add("hidden"); $("#projectView").classList.remove("hidden"); $("#projectTitle").textContent = current.name; const source = current.source ? `${current.source.filename} · ${(current.source.size / 1024).toFixed(1)} KB` : "尚未上传 DWG"; $("#projectMeta").textContent = `${current.status} · ${source}`; const rows = current.bom?.rows || []; const cabinets = new Set(rows.map(r => r.cabinet)).size; $("#stats").innerHTML = [["柜体", cabinets], ["BOM 项目", rows.length], ["材料数量", rows.reduce((n, r) => n + Number(r.quantity || 0), 0)], ["待人工处理", rows.filter(r => r.status !== "AI识别").length]].map(x => `<div class="stat"><div class="stat-label">${x[0]}</div><div class="stat-value">${x[1]}</div></div>`).join(""); renderRows(rows); }
function coordText(coords) { return (coords || []).map(p => `(${Number(p.x).toFixed(3)}, ${Number(p.y).toFixed(3)})`).join("\n"); }
function rowLookup(row, key, entity) { if (row[key]) return row[key]; const record = catalogData[entity].find(item => item.id === row[`${entity === "brands" ? "brand" : entity === "products" ? "product" : "price"}_id`]); return record ? (record.name || record.model || (record.unit_price !== undefined ? `${record.unit_price} ${record.currency || ""}` : "")) : ""; }
function matchStatus(row) { if (row.price_id) return { text: "已匹配价格", cls: "price" }; if (row.brand_id || row.product_id) return { text: "已选择品牌", cls: "brand" }; return { text: "未选择品牌", cls: "" }; }
function rowPrice(row) { if (row.price_value !== undefined && row.price_value !== null && row.price_value !== "") return `${row.price_value} ${row.price_currency || "CNY"}`; const price = catalogData.prices.find(item => item.id === row.price_id); return price ? `${price.unit_price} ${price.currency || "CNY"}` : "—"; }
function renderRows(rows) { $("#noBom").classList.toggle("hidden", rows.length > 0); $("#bomBody").innerHTML = rows.map((r, i) => { const status = matchStatus(r); return `<tr data-index="${i}"><td><input class="cell-input" data-k="cabinet" value="${esc(r.cabinet)}"></td><td><input class="cell-input" data-k="category" value="${esc(r.category)}"></td><td><input class="cell-input" data-k="spec" value="${esc(r.spec)}"></td><td><input class="cell-input" data-k="quantity" type="number" min="0" step="1" value="${Number(r.quantity || 0)}"></td><td>${esc(rowLookup(r, "brand_name", "brands") || "—")}</td><td>${esc(rowLookup(r, "product_model", "products") || "—")}</td><td>${esc(rowPrice(r))}</td><td><span class="match-status ${status.cls}">${status.text}</span></td><td><select class="cell-select" data-k="status">${["AI识别", "人工确认", "人工添加"].map(s => `<option ${r.status === s ? "selected" : ""}>${s}</option>`).join("")}</select></td><td class="raw-cell">${esc((r.rawTexts || []).join("\n"))}</td><td class="coord-cell">${esc(coordText(r.coords))}</td><td class="rule-cell">${esc((r.rules || []).join("；"))}</td><td><button class="match-button" data-match="${i}">选择品牌</button><button class="delete-button" data-delete="${i}">删除</button></td></tr>`; }).join(""); document.querySelectorAll("#bomBody [data-k]").forEach(el => el.addEventListener("input", () => { const row = current.bom.rows[Number(el.closest("tr").dataset.index)]; row[el.dataset.k] = el.dataset.k === "quantity" ? Number(el.value) : el.value; if (el.dataset.k !== "status" && row.status === "AI识别") row.status = "人工确认"; })); document.querySelectorAll("[data-match]").forEach(el => el.addEventListener("click", () => openBrandDrawer(Number(el.dataset.match)))); document.querySelectorAll("[data-delete]").forEach(el => el.addEventListener("click", () => { current.bom.rows.splice(Number(el.dataset.delete), 1); renderCurrent(); })); }
function newProjectForm(show = true) { $("#newProjectForm").classList.toggle("hidden", !show); if (show) $("#projectNameInput").focus(); }
async function createProject(e) { e.preventDefault(); const name = $("#projectNameInput").value.trim(); if (!name) return; current = await api("/api/projects", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name }) }); $("#projectNameInput").value = ""; newProjectForm(false); await loadProjects(); renderCurrent(); }
async function uploadDwg(e) { const file = e.target.files[0]; if (!file || !current) return; showNotice("正在转换 DWG 并生成 BOM，请稍候……"); $("#headerStatus").textContent = "分析中"; try { current = await api(`/api/projects/${current.id}/dwg`, { method: "POST", headers: { "content-type": "application/octet-stream", "x-file-name": encodeURIComponent(file.name) }, body: file }); await loadProjects(); renderCurrent(); showNotice(`分析完成：已生成 ${current.bom?.rows?.length || 0} 条 BOM 项目。`); } catch (err) { showNotice(err.message, true); } finally { e.target.value = ""; $("#headerStatus").textContent = current ? "已登录" : "未登录"; } }
async function save() { if (!current) return; try { current = await api(`/api/projects/${current.id}/bom`, { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ rows: current.bom.rows }) }); await loadProjects(); renderCurrent(); showNotice("修改已保存。"); } catch (err) { showNotice(err.message, true); } }
function addForm() { const el = $("#addForm"); el.classList.toggle("hidden"); if (!el.classList.contains("hidden")) { el.innerHTML = `<div class="add-grid"><label>柜体<input id="addCabinet" value="${esc(current?.bom?.rows?.[0]?.cabinet || "")}"></label><label>材料类别<input id="addCategory" placeholder="例如 断路器"></label><label>规格<input id="addSpec" placeholder="例如 3P 200A"></label><label>数量<input id="addQty" type="number" value="1" min="1"></label><label>状态<select id="addStatus"><option>人工添加</option><option>人工确认</option></select></label><button class="primary compact" id="confirmAdd">加入</button></div>`; $("#confirmAdd").addEventListener("click", () => { const row = { id: crypto.randomUUID(), cabinet: $("#addCabinet").value, category: $("#addCategory").value, spec: $("#addSpec").value, quantity: Number($("#addQty").value || 1), status: $("#addStatus").value, rawTexts: [], coords: [], rules: ["人工添加"], note: "" }; if (!row.cabinet || !row.category || !row.spec) { showNotice("请至少填写柜体、材料类别和规格。", true); return; } current.bom.rows.push(row); el.classList.add("hidden"); renderCurrent(); }); } }
async function exportExcel() { if (!current) return; try { await save(); const result = await api(`/api/projects/${current.id}/export`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ rows: current.bom.rows }) }); const a = document.createElement("a"); a.href = result.url; a.download = result.filename; document.body.appendChild(a); a.click(); a.remove(); showNotice("Excel 已生成并开始下载。"); } catch (err) { showNotice(err.message, true); } }
function moneyText(value) { return `${Number(value || 0).toFixed(2)} CNY`; }
function quotationNotice(message, error = false) { const el = $("#quotationNotice"); el.textContent = message || ""; el.classList.toggle("hidden", !message); el.classList.toggle("error", error); }
function renderQuotation() { if (!quotation) return; $("#quotationTitle").textContent = current?.name || "项目报价"; $("#laborFeeInput").value = Number(quotation.laborFee || 0); $("#transportFeeInput").value = Number(quotation.transportFee || 0); $("#otherFeeInput").value = Number(quotation.otherFee || 0); $("#profitRateInput").value = Number(quotation.profitRate || 0); const unmatched = (quotation.items || []).filter(item => !item.priceMatched).length; $("#quotationSummary").innerHTML = [["材料成本", moneyText(quotation.materialCost)], ["附加费用", moneyText(Number(quotation.laborFee || 0) + Number(quotation.transportFee || 0) + Number(quotation.otherFee || 0))], ["利润", `${moneyText(quotation.profitAmount)} · ${Number(quotation.profitRate || 0)}%`], ["最终报价", moneyText(quotation.totalAmount), "total"]].map(([label, value, cls]) => `<div class="quotation-stat ${cls || ""}"><div class="quotation-stat-label">${label}</div><div class="quotation-stat-value">${value}</div></div>`).join(""); $("#quotationBody").innerHTML = (quotation.items || []).map(item => `<tr><td>${esc(item.cabinet)}</td><td>${esc(item.category)}</td><td>${esc(item.spec)}</td><td>${Number(item.quantity || 0)}</td><td>${esc(item.brandName || "—")}</td><td>${esc(item.productModel || "—")}</td><td>${item.priceMatched ? moneyText(item.unitPrice) : "—"}</td><td>${moneyText(item.materialCost)}</td><td class="${item.priceMatched ? "priced" : "unpriced"}">${item.priceMatched ? "已匹配价格" : "未匹配价格"}</td></tr>`).join(""); quotationNotice(unmatched ? `有 ${unmatched} 条材料未匹配采购价格，当前按 0 计入材料成本。` : "所有材料均已匹配采购价格。", Boolean(unmatched)); }
async function openQuotation() { if (!current) return; $("#projectModule").classList.remove("hidden"); $("#projectView").classList.add("hidden"); $("#quotationView").classList.remove("hidden"); quotationNotice("正在读取报价数据……"); try { const result = await api(`/api/projects/${current.id}/quotation`); const existing = result.quotation; const synced = await api(`/api/projects/${current.id}/quotation`, { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ rows: current.bom?.rows || [], laborFee: existing?.laborFee || 0, transportFee: existing?.transportFee || 0, otherFee: existing?.otherFee || 0, profitRate: existing?.profitRate || 0 }) }); quotation = synced.quotation; renderQuotation(); await loadPdfHistory(); } catch (error) { quotationNotice(error.message, true); } }
async function saveQuotation() { if (!current) return; try { const result = await api(`/api/projects/${current.id}/quotation`, { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ rows: current.bom?.rows || [], laborFee: Number($("#laborFeeInput").value || 0), transportFee: Number($("#transportFeeInput").value || 0), otherFee: Number($("#otherFeeInput").value || 0), profitRate: Number($("#profitRateInput").value || 0) }) }); quotation = result.quotation; renderQuotation(); quotationNotice("报价已保存并重新计算。", false); } catch (error) { quotationNotice(error.message, true); } }
async function loadPdfHistory() { if (!current) return; try { const result = await api(`/api/projects/${current.id}/quotation/pdf-history`); const items = result.items || []; $("#pdfHistoryList").innerHTML = items.length ? items.map(item => `<div class="history-item"><div class="history-meta">${esc(item.customerName || "未填写客户")}<small>${esc(new Date(item.createdAt).toLocaleString("zh-CN"))}${item.customerContact ? ` · ${esc(item.customerContact)}` : ""}${item.customerPhone ? ` · ${esc(item.customerPhone)}` : ""}</small></div><div class="history-actions"><button class="secondary compact" data-regenerate="${esc(item.id)}">重新生成</button><a href="${esc(item.downloadUrl)}" download="${esc(item.filename)}">下载 PDF</a></div></div>`).join("") : `<div class="history-empty">还没有生成过客户报价 PDF。</div>`; document.querySelectorAll("[data-regenerate]").forEach(button => button.addEventListener("click", () => { const item = items.find(entry => entry.id === button.dataset.regenerate); if (!item) return; $("#customerNameInput").value = item.customerName || ""; $("#customerContactInput").value = item.customerContact || ""; $("#customerPhoneInput").value = item.customerPhone || ""; $("#customerAddressInput").value = item.customerAddress || ""; $("#customerNotesInput").value = item.notes || ""; generateQuotationPdf(); })); } catch (error) { $("#pdfHistoryList").innerHTML = `<div class="history-empty">历史报价加载失败：${esc(error.message)}</div>`; } }
async function generateQuotationPdf() { if (!current) return; try { const result = await api(`/api/projects/${current.id}/quotation/pdf`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ customerName: $("#customerNameInput").value, customerContact: $("#customerContactInput").value, customerPhone: $("#customerPhoneInput").value, customerAddress: $("#customerAddressInput").value, notes: $("#customerNotesInput").value }) }); await loadPdfHistory(); const pdfDocument = result.document; const link = document.createElement("a"); link.href = pdfDocument.downloadUrl; link.download = pdfDocument.filename; document.body.appendChild(link); link.click(); link.remove(); quotationNotice("客户报价 PDF 已生成并保存到历史报价。", false); } catch (error) { quotationNotice(error.message, true); } }
$("#quotationButton").addEventListener("click", openQuotation); $("#backToBomButton").addEventListener("click", renderCurrent); $("#saveQuotationButton").addEventListener("click", saveQuotation); $("#generatePdfButton").addEventListener("click", generateQuotationPdf);
async function login(e) { e.preventDefault(); const error = $("#loginError"); error.classList.add("hidden"); try { const result = await api("/api/auth/login", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ email: $("#loginEmail").value, password: $("#loginPassword").value }) }); showApp(result.user); await loadProjects(); } catch (err) { error.textContent = err.message; error.classList.remove("hidden"); } }
async function logout() { await fetch("/api/auth/logout", { method: "POST" }); current = null; projects = []; sessionUser = null; showLogin(); }
