  products: { title: "产品型号", description: "平台公共产品型号及品牌、材料关联。普通企业只读。", public: true, columns: [{ k: "model", l: "型号" }, { k: "specification", l: "规格" }, { k: "brand_id", l: "品牌" }, { k: "material_id", l: "材料" }, { k: "unit", l: "单位" }], fields: [{ k: "model", l: "型号", required: true }, { k: "specification", l: "规格" }, { k: "brand_id", l: "品牌", select: "brands" }, { k: "material_id", l: "材料", select: "materials" }, { k: "unit", l: "单位" }, { k: "description", l: "说明", area: true }] },
